pub fn parse_age(s: &str) -> Result<u32, String> {
    s.parse::<u32>().map_err(|e| e.to_string())
}

pub fn parse_score(s: &str) -> Result<f64, String> {
    let v: f64 = s.parse().map_err(|e: std::num::ParseFloatError| e.to_string())?;
    if v < 0.0 || v > 100.0 {
        return Err(format!("score out of range: {}", v));
    }
    Ok(v)
}

pub fn parse_username(s: &str) -> Result<String, String> {
    if s.is_empty() {
        return Err("username cannot be empty".to_string());
    }
    if s.len() > 20 {
        return Err(format!("username too long: {}", s.len()));
    }
    Ok(s.to_string())
}

use apperrors::{parse_age, parse_score, parse_username};

#[test]
fn test_parse_age_ok() {
    assert_eq!(parse_age("25").unwrap(), 25);
}

#[test]
fn test_parse_age_err() {
    assert!(parse_age("abc").is_err());
}

#[test]
fn test_parse_score_range_err() {
    assert!(parse_score("150.0").is_err());
}

