#[derive(Debug, PartialEq)]
pub enum AppError {
    ParseInt(String),
    ParseFloat(String),
    Validation(String),
}

impl std::fmt::Display for AppError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            AppError::ParseInt(m) => write!(f, "parse int error: {}", m),
            AppError::ParseFloat(m) => write!(f, "parse float error: {}", m),
            AppError::Validation(m) => write!(f, "validation error: {}", m),
        }
    }
}

